'use strict';
// data/voice/deedee.js — deedee's baked clips (loaded after data/voice-clips.js). Merge from the Voice Baker; do not hand-edit.
VOICE_CLIPS.clips.deedee={"greet":[{"text":"My favorite son!","mp3":"","model":"eleven_v4"},{"text":"Girls! I love you to the moon and back!","mp3":"","model":"eleven_v4"},{"text":"Who wants rhubarb crisp? Everyone wants rhubarb crisp.","mp3":"","model":"eleven_v4"}],"basic":[{"text":"Hold still! You've got a smudge!","mp3":"","model":"eleven_v4"},{"text":"Spit shine! There. Much better.","mp3":"","model":"eleven_v4"}],"beanie_master_open":[{"text":"I am the Beanie Master!","mp3":"","model":"eleven_v4"}],"beanie_master":[{"text":"Oh my!","mp3":"","model":"eleven_v4"}],"brisk_means_brisk":[{"text":"Brisk means brisk. Keep your arms moving.","mp3":"","model":"eleven_v4"}],"corner_piece":[{"text":"Corner-piece privilege. I saved the good bit.","mp3":"","model":"eleven_v4"}],"crisp":[{"text":"Fresh rhubarb crisp! Careful, it's HOT!","mp3":"","model":"eleven_v4"}],"dc1":[{"text":"Faster, honey! Clean as you go!","mp3":"","model":"eleven_v4"}],"dc2":[{"text":"Rome, then Florence, then the coast. I made a binder.","mp3":"","model":"eleven_v4"}],"dc3":[{"text":"Everybody eat! Wait, the gumbo goes HERE. Elbows off!","mp3":"","model":"eleven_v4"}],"dcff3":[{"text":"Keep up, honey! Arms at ninety!","mp3":"","model":"eleven_v4"}],"dinner":[{"text":"Dinner's ready! Nobody leaves this table hungry!","mp3":"","model":"eleven_v4"}],"dish_towel_flick":[{"text":"Dish-towel flick. You had a spot.","mp3":"","model":"eleven_v4"}],"ff3":[{"text":"Fifty-one years, Boppy. I'd do every single day again!","mp3":"","model":"eleven_v4"}],"garden_shower":[{"text":"Garden shower. You looked a little wilted.","mp3":"","model":"eleven_v4"}],"grandma_squeeze":[{"text":"Come here, you! One big squeeze!","mp3":"","model":"eleven_v4"}],"hug":[{"text":"To the moon and back! Everybody in!","mp3":"","model":"eleven_v4"}],"hurt":[{"text":"Oh! Well, I never!","mp3":"","model":"eleven_v4"},{"text":"Ow! That needs ice. Trust me, I'm a nurse!","mp3":"","model":"eleven_v4"}],"join":[{"text":"Room for one more? Deedee brings cookies, hugs, and love to the moon and back!","mp3":"","model":"eleven_v4"}],"ko":[{"text":"I'm just resting my eyes.","mp3":"","model":"eleven_v4"}],"low":[{"text":"Deedee needs a little sit-down, girls.","mp3":"","model":"eleven_v4"},{"text":"Somebody pour me a glass of wine.","mp3":"","model":"eleven_v4"}],"moon_back":[{"text":"To the moon and back! Everybody in!","mp3":"","model":"eleven_v4"}],"moon_ult":[{"text":"Hold on tight! I love this family to the moon and back!","mp3":"","model":"eleven_v4"}],"moonshot":[{"text":"I love you to the moon... AND BACK!","mp3":"","model":"eleven_v4"}],"mop":[{"text":"I just mopped! Watch your step!","mp3":"","model":"eleven_v4"}],"nurse":[{"text":"Retired registered nurse! Little pinch, honey!","mp3":"","model":"eleven_v4"}],"oven_mitt_ultimatum":[{"text":"Oven mitt ultimatum. Enough of that.","mp3":"","model":"eleven_v4"}],"praise":[{"text":"Come on, honey. Deedee hasn't missed a dance floor in fifty years. One, two, three.","mp3":"","model":"eleven_v4"},{"text":"Shoes off, everybody! Floors just mopped! Let's DANCE!","mp3":"","model":"eleven_v4"}],"registered_nut":[{"text":"Registered nut, reporting. Let me see that.","mp3":"","model":"eleven_v4"}],"rise_and_shine":[{"text":"Rise and shine! The day is wasting!","mp3":"","model":"eleven_v4"}],"sunday_ult":[{"text":"Wash your hands, everybody! Sunday dinner is on the table!","mp3":"","model":"eleven_v4"}],"tombo2":[{"text":"Pull, honey! Roots and all!","mp3":"","model":"eleven_v4"}],"tombo3":[{"text":"Needs salt. Who cleaned this counter?!","mp3":"","model":"eleven_v4"}],"tombo":[{"text":"Did you SEE what it was wearing?","mp3":"","model":"eleven_v4"}],"walk":[{"text":"Ten thousand steps! Keep up, honey!","mp3":"","model":"eleven_v4"}],"wet_floor":[{"text":"I just mopped! Watch your step!","mp3":"","model":"eleven_v4"}],"wine":[{"text":"Just one glass! It's five o'clock somewhere!","mp3":"","model":"eleven_v4"}],"win":[{"text":"My girls did it! To the moon and back!","mp3":"","model":"eleven_v4"},{"text":"Rhubarb crisp for everyone! You earned it!","mp3":"","model":"eleven_v4"}]};
